{
  "summary": {
    "failed_because": "The injected anomalies did not materially overlap with the measurement window and/or did not create sustained contention on the critical path of the probe workload. As a result, after_metrics improved (p95 latency dropped, QPS slightly increased) instead of degrading."
  },
  "evidence": {
    "measured_outcome": {
      "baseline": {
        "qps": 15.7676,
        "avg_latency_ms": 15.9644,
        "p95_latency_ms": 32.732,
        "p99_latency_ms": 88.0685,
        "threads": 40,
        "duration_sec": 12
      },
      "after": {
        "qps": 16.3621,
        "avg_latency_ms": 13.1303,
        "p95_latency_ms": 15.2813,
        "p99_latency_ms": 50.3236,
        "threads": 40,
        "duration_sec": 12
      },
      "expected_effects": [
        "qps_down",
        "p95_latency_up"
      ],
      "observed_direction": "opposite_of_expected"
    },
    "timing_mismatch_signals": [
      "database_backup spec had start_after_seconds=60 but task executed immediately (start_after_sec=0.0) and finished quickly (~1.8s for CTAS), so it likely did not overlap with the 'after' probe window in a meaningful way.",
      "metadata_lock task_spec describes holding an MDL via LOCK TABLES orders WRITE + SELECT SLEEP(480) plus a DDL waiter, but execution_trace shows only a single query held for 16s: SELECT COUNT(*) FROM new_orders ... (no evidence the LOCK TABLES/DDL steps actually ran).",
      "io injection ran chaosblade disk burn for /home; unclear if DB files are on /home (often /var/lib/mysql, docker volume, or different mount). If not co-located, the disk burn would not impact MySQL I/O."
    ],
    "insufficient_pressure_signals": [
      "traffic surge ran 500 threads but achieved only ~64.8 QPS with low p95 (~17.9ms). That indicates either the workload driver is lightweight, server is underutilized, or the driver is bottlenecked (client-side), so DB contention may not have increased.",
      "backup implemented as CREATE TABLE ... AS SELECT * FROM orders completed in ~1.8s; too short/small to produce sustained IO/lock contention.",
      "no failed transactions, no explicit lock wait/blocked transaction evidence captured in db_evidence."
    ]
  },
  "root_cause_analysis": [
    {
      "root_cause": "Lack of real metadata lock conflict",
      "why_it_matters": "Without a concurrent DDL waiting on an MDL held by a long-running transaction (or explicit LOCK TABLES held open), you won't see lock_wait_time_up or broad latency impact.",
      "concrete_issue_in_trace": "Only 'hold_metadata_lock' executed as a single SELECT held for 16s; no executed LOCK TABLES or ALTER TABLE step in trace output."
    },
    {
      "root_cause": "Backup/IO workload not heavy and/or not overlapping",
      "why_it_matters": "A quick CTAS (~1.8s) won’t create measurable p95/QPS degradation in a 12s probe unless perfectly overlapped and sufficiently large.",
      "concrete_issue_in_trace": "Backup finished quickly; planned mysqldump-like options were not actually used; and spec start_after_seconds=60 was not honored."
    },
    {
      "root_cause": "Disk burn likely targeted the wrong filesystem",
      "why_it_matters": "Chaosblade disk burn affects a path; if MySQL data/log files aren’t on that path, DB latency won’t move.",
      "concrete_issue_in_trace": "Command used --path /home with --read; many deployments store DB under /var/lib/mysql or a mounted volume."
    },
    {
      "root_cause": "Measurement design didn’t capture the anomaly window",
      "why_it_matters": "If you measure 'after' when anomalies are already over (or not started), metrics can look normal or better due to noise/warmup effects.",
      "concrete_issue_in_trace": "All tasks have start_after_sec=0.0 and short durations; 'after' probe is a separate 12s window with no explicit synchronization to ensure overlap."
    }
  ],
  "concrete_changes": {
    "1_fix_scheduling_and_overlap": [
      {
        "change": "Enforce start_after_seconds / dependency timing in the executor (do not ignore start_after_seconds).",
        "how": "Ensure task runner respects start_after_seconds and dependency graph; start the 'after' probe while anomalies are active (e.g., begin probe at t=5s, run for 20-30s).",
        "acceptance_criteria": "A timeline log shows anomaly start/end timestamps and probe timestamps with >=70% overlap."
      },
      {
        "change": "Increase probe duration and run multiple trials.",
        "how": "Baseline: 60s; Injection+probe: 60s; compute delta with confidence intervals or at least median of 3 runs.",
        "acceptance_criteria": "Reduced variance; p95 change direction is consistent across runs."
      }
    ],
    "2_make_metadata_lock_real_and_observable": [
      {
        "change": "Actually execute the two-session MDL scenario (holder + ddl_waiter) and capture lock waits.",
        "how": [
          "Session A: SET autocommit=0; LOCK TABLES orders WRITE; DO SLEEP(120); (do not UNLOCK until end).",
          "Session B (after 5s): ALTER TABLE orders ADD COLUMN agent_mdl_probe INT NULL; (expect to block).",
          "Set low lock wait timeout for quicker signal in logs: SET SESSION lock_wait_timeout=5 (or innodb_lock_wait_timeout for row locks)."
        ],
        "acceptance_criteria": [
          "performance_schema.metadata_locks shows a pending lock request for the ALTER TABLE session.",
          "SHOW PROCESSLIST shows ALTER TABLE in 'Waiting for table metadata lock'."
        ]
      },
      {
        "change": "Ensure the 'hold_metadata_lock' step is not a plain SELECT sleep wrapper.",
        "how": "Replace hold step with explicit LOCK TABLES / long transaction that holds MDL, not just long query time.",
        "acceptance_criteria": "Trace includes executed LOCK TABLES and ALTER TABLE statements (with elapsed time for ALTER reflecting blocking)."
      }
    ],
    "3_make_IO_pressure_target_the_mysql_storage": [
      {
        "change": "Burn I/O on the actual MySQL datadir or underlying block device.",
        "how": [
          "Detect datadir: SHOW VARIABLES LIKE 'datadir';",
          "Use chaosblade path = that datadir mount (or run fio against that path).",
          "Use mixed read/write and fsync: e.g., fio randrw, direct=1, iodepth=16, numjobs=4, size=2-10GB, runtime=60."
        ],
        "acceptance_criteria": [
          "iostat shows increased await/util on the DB device during injection.",
          "MySQL shows increased Innodb_data_reads/writes or log waits during injection window."
        ]
      },
      {
        "change": "Increase duration to exceed probe window.",
        "how": "Run IO burn 60-120s; start probe after 10s warmup while burn continues.",
        "acceptance_criteria": "p95 latency increases during overlap window, not only outside it."
      }
    ],
    "4_make_backup_workload_actually_backup_like": [
      {
        "change": "Replace CTAS with a logical dump or a heavier physical-like scan that lasts long enough.",
        "how": [
          "Option A: mysqldump with --single-transaction on large tables, writing to local disk; throttle off to maximize IO.",
          "Option B: SELECT * FROM orders JOIN order_line ... INTO OUTFILE (or client-side fetch) to force sustained reads.",
          "Option C: If staying in-SQL, copy multiple large tables and add ORDER BY to force filesort/temp tables: CREATE TABLE ... AS SELECT ... ORDER BY some_col."
        ],
        "acceptance_criteria": "Backup task runtime >= 30-60s and coincides with probe; disk read throughput increases measurably."
      },
      {
        "change": "If you want lock impact, intentionally use LOCK TABLES (not --single-transaction) in a controlled environment.",
        "how": "Run LOCK TABLES orders READ; keep open for 60s; measure impact on writers.",
        "acceptance_criteria": "Application writes block and lock wait metrics increase (with safety limits)."
      }
    ],
    "5_tighten_workload_to_hit_the_contended_objects": [
      {
        "change": "Align the probe workload with the contended table(s).",
        "how": "If inducing MDL on `orders`, ensure probe workload performs writes/reads to `orders` frequently (or directly run a probe that updates/inserts into orders).",
        "acceptance_criteria": "When MDL blocks, probe latencies spike and QPS drops (not just unrelated queries)."
      },
      {
        "change": "Validate server-side saturation vs client-side bottleneck for traffic_surge.",
        "how": [
          "Increase thread_count gradually (50/100/200) and observe server CPU/IO/active connections.",
          "If QPS stops scaling while server metrics stay low, the driver is bottlenecked; run the driver closer to DB, increase driver resources, or use fewer threads with heavier queries."
        ],
        "acceptance_criteria": "Active connections and server resource utilization increase along with concurrency."
      }
    ],
    "6_add_missing_index_anomaly_or drop it explicitly": [
      {
        "change": "Implement missing_index step (it was planned but not executed).",
        "how": [
          "Pick a real high-cardinality predicate used by workload and remove/avoid index usage (e.g., add a query with WHERE nonindexed_col=... on a large table).",
          "Or explicitly FORCE INDEX (none) equivalent by rewriting query to defeat index, then run it at concurrency."
        ],
        "acceptance_criteria": "EXPLAIN shows full table scan; handler_read_rnd_next and tmp tables increase; slow query log captures the query."
      }
    ],
    "7_improve observability to explain failures": [
      {
        "change": "Collect DB evidence during injection: locks, waits, top SQL, and resource metrics.",
        "how": [
          "Enable performance_schema consumers for metadata_locks and events_waits.",
          "Capture: SHOW ENGINE INNODB STATUS; SHOW PROCESSLIST; SELECT * FROM performance_schema.metadata_locks; sys.schema_table_lock_waits; sys.statement_analysis.",
          "Record OS: iostat/vmstat/top during injection."
        ],
        "acceptance_criteria": "Post-run report includes at least one direct indicator for each intended anomaly (MDL wait, IO util spike, backup runtime)."
      }
    ]
  },
  "most_likely_single_point_of_failure": {
    "item": "metadata_lock was not actually created (missing LOCK TABLES + blocked DDL execution), and the measurement window likely did not overlap strong anomalies.",
    "because": "Trace lacks executed lock-holder/ddl-waiter SQL; and the 'after' probe shows improved latency which is consistent with 'no real contention during measurement'."
  }
}
